// browser_wait_for 实现：用 Promise + 轮询在页面里等待，最长 30s
#include "browser_wait_for.h" // 自身声明
#include "browser_tool/tool_helpers.h" // EvalReply
#include "utils/js_builder.h" // js::Literal
#include "utils/json_util.h" // 参数读取
namespace { const int kMaxWaitMs = 30000; int ClampMs(int ms) { return ms > kMaxWaitMs ? kMaxWaitMs : ms; } } // 最长等待与钳位
void BrowserWaitForTool::Run(const ToolRequest& req) { double seconds = 0; ArgGetDouble(req.args, "time", seconds); std::string text, gone; const bool has_text = ArgGetString(req.args, "text", text) && !text.empty(); const bool has_gone = ArgGetString(req.args, "textGone", gone) && !gone.empty(); std::string script; if (!has_text && !has_gone) { const int wait_ms = ClampMs(seconds > 0 ? static_cast<int>(seconds * 1000) : 1000); script = "new Promise(function(res){setTimeout(function(){res('已等待 " + std::to_string(wait_ms) + "ms');}, " + std::to_string(wait_ms) + ");})"; } else { const int deadline = ClampMs(seconds > 0 ? static_cast<int>(seconds * 1000) : 10000); script = std::string("new Promise(function(res){var needle=") + js::Literal(has_text ? text : gone) + ";var gone=" + (has_gone ? "true" : "false") + ";var end=Date.now()+" + std::to_string(deadline) + ";function has(){return document.body?(document.body.innerText||'').indexOf(needle)>=0:false;}" "function tick(){if(gone?!has():has()){res(gone?'文本已消失':'文本已出现');return;}" "if(Date.now()>end){res(gone?'等待超时：文本仍在':'等待超时：未出现该文本');return;}" "setTimeout(tick,200);}tick();})"; } tool::EvalReply(req, script, "message", true, "等待失败"); } // 无条件则按 time 睡眠；有 text/textGone 则 200ms 轮询页面文本，超时也返回说明性结果
